/**
 * AI Finder service layer — deterministic mock logic.
 * Structure is designed so interpretQuery/rankProps can later be replaced
 * with a real AI model (OpenAI, Anthropic, etc.) without rebuilding the page.
 */

import type { PropResearchItem } from "../../app/research/mockData";
import type { EliteResearchAnalysis } from './eliteResearchFilter';
import type { DeepResearchCard } from '../finder/deepResearchCard';
import { dateIntentFromText, type NaturalDateIntent } from '../dateModel';

// ─── types ────────────────────────────────────────────────────────────────────

export interface AiSearchCriteria {
  sport: string;
  dateIntent: NaturalDateIntent | null;
  playerType: "hitter" | "pitcher" | "any";
  propTypes: string[];
  side: "Over" | "Under" | "any";
  minConfidence: number;
  minL10: number;
  minL5: number;
  riskLevel: "LOW" | "MEDIUM" | "HIGH" | "any";
  maxResults: number;
  teams: string[];
  plusMoneyOnly: boolean;
  rawQuery: string;
  summaryText: string;
}

export interface AiResult {
  prop: PropResearchItem;
  eliteResearch?: EliteResearchAnalysis;
  deepResearch?: DeepResearchCard;
  matchScore: number;    // 0-100: how well the prop matches the user's search
  riskLevel: "LOW" | "MEDIUM" | "HIGH";
  matchReasons: string[];
  riskNotes: string[];
  aiReason: string;
}

// ─── interpret ────────────────────────────────────────────────────────────────

/** Convert a free-text query into structured search criteria. */
export function interpretQuery(rawQuery: string): AiSearchCriteria {
  const q = rawQuery.toLowerCase();

  // ── sport ────────────────────────────────────────────────────────────────────
  const sport =
    q.includes("nba") || q.includes("basketball") ? "NBA" :
    q.includes("nfl") || q.includes("football") ? "NFL" :
    q.includes("nhl") || q.includes("hockey") ? "NHL" : "MLB";

  // ── player type ───────────────────────────────────────────────────────────
  const pitcherTerms = ["pitcher", "strikeout", "starting pitcher", " ks "];
  const hitterTerms = ["hitter", "batter", "hits", "home run", "total base", "rbi", "bats"];
  const isPitcher = pitcherTerms.some((t) => q.includes(t)) && !hitterTerms.some((t) => q.includes(t));
  const isHitter = hitterTerms.some((t) => q.includes(t));
  const playerType: AiSearchCriteria["playerType"] = isPitcher ? "pitcher" : isHitter ? "hitter" : "any";

  // ── prop types ────────────────────────────────────────────────────────────
  const propTypes: string[] = [];
  if (q.includes("home run") || q.includes("homer") || /\bhr\b/.test(q)) propTypes.push("Home Runs");
  if (q.includes("total base") || /\btb\b/.test(q)) propTypes.push("Total Bases");
  if (/\bhits?\b/.test(q) && !q.includes("homer")) propTypes.push("Hits");
  if (q.includes("strikeout") || /\bk\b/.test(q)) propTypes.push("Strikeouts");
  if (q.includes("rbi")) propTypes.push("RBIs");
  if (/\bruns?\b/.test(q) && !q.includes("home run")) propTypes.push("Runs");

  // ── side ──────────────────────────────────────────────────────────────────
  const side: AiSearchCriteria["side"] =
    /\bovers?\b/.test(q) ? "Over" : /\bunders?\b/.test(q) ? "Under" : "any";

  // ── confidence threshold ──────────────────────────────────────────────────
  let minConfidence = 65;
  if (/high confidence|best plays|strongest|premium/i.test(q)) minConfidence = 78;
  if (/low.?risk|safe|conservative|careful/i.test(q)) minConfidence = 72;
  const confMatch = q.match(/(\d{2,3})%?\s*(?:confidence|conf|min)/);
  if (confMatch) minConfidence = Math.min(95, parseInt(confMatch[1]));

  // ── L10 hit rate ──────────────────────────────────────────────────────────
  let minL10 = 0;
  if (/strong recent|good recent|hot streak|trending/i.test(q)) minL10 = 65;
  const l10Match = q.match(/(\d{2,3})%?\s*l10/i) || q.match(/l10\s*(\d{2,3})%?/i);
  if (l10Match) minL10 = parseInt(l10Match[1]);

  // ── risk level ────────────────────────────────────────────────────────────
  const riskLevel: AiSearchCriteria["riskLevel"] =
    /low.?risk|safe|conservative|careful/i.test(q) ? "LOW" :
    /high.?risk|volatile|risky|aggressive/i.test(q) ? "HIGH" : "any";

  // ── max results ───────────────────────────────────────────────────────────
  // A ceiling, never a quota — fewer qualifying picks are returned as-is.
  // Allows modifiers between the count and the noun ("15 best MLB plays").
  const numMatch = q.match(/\b(\d+)\s+(?:[a-z][a-z+-]*\s+){0,4}?(?:plays?|props?|picks?|results?|opportunities?)\b/i);
  const maxResults = numMatch ? Math.min(15, Math.max(1, parseInt(numMatch[1]))) : 15;

  // ── plus money ────────────────────────────────────────────────────────────
  const plusMoneyOnly = /plus.?money|\+money|value plays|plus odds/i.test(q);

  // ── team filters ──────────────────────────────────────────────────────────
  const teams: string[] = [];
  if (/yankees?|\bnyy\b/i.test(q)) teams.push("Yankees");
  if (/red sox|\bbos\b/i.test(q)) teams.push("Red Sox");
  if (/dodgers?|\blad\b/i.test(q)) teams.push("Dodgers");
  if (/giants?|\bsfg\b/i.test(q)) teams.push("Giants");
  if (/phillies?|\bphi\b/i.test(q)) teams.push("Phillies");
  if (/marlins?|\bmia\b/i.test(q)) teams.push("Marlins");

  // ── build human-readable summary ──────────────────────────────────────────
  const parts: string[] = [];
  if (maxResults < 15) parts.push(`${maxResults}`);
  if (riskLevel === "LOW") parts.push("low-risk");
  if (plusMoneyOnly) parts.push("plus-money");
  if (minConfidence >= 78) parts.push("high-confidence");
  if (playerType === "hitter") parts.push("hitter");
  if (playerType === "pitcher") parts.push("pitcher");
  if (propTypes.length > 0) parts.push(propTypes.map((p) => p.toLowerCase()).join("/"));
  if (side !== "any") parts.push(`${side.toLowerCase()} props`);
  else parts.push("MLB plays");
  if (teams.length > 0) parts.push(`(${teams.join(", ")})`);
  if (minL10 > 0) parts.push(`with L10 ≥ ${minL10}%`);

  return {
    sport, dateIntent: dateIntentFromText(rawQuery), playerType, propTypes, side,
    minConfidence, minL10, minL5: 0,
    riskLevel, maxResults, teams, plusMoneyOnly,
    rawQuery, summaryText: parts.join(" "),
  };
}

// ─── rank ─────────────────────────────────────────────────────────────────────

/** Score and rank props against interpreted search criteria. */
export function rankProps(props: PropResearchItem[], criteria: AiSearchCriteria): AiResult[] {
  const PITCHER_PROPS = ["Strikeouts", "Walks", "Innings Pitched", "Outs Pitched"];

  const scored = props
    .filter((p) => p.sport === criteria.sport)
    .map((prop): AiResult | null => {
      const reasons: string[] = [];
      const riskNotes: string[] = [];
      let score = 0;
      let maxScore = 0;

      const isPitcherProp = PITCHER_PROPS.includes(prop.propType);
      const propOdds = parseFloat(prop.overOdds);

      // prop type match
      if (criteria.propTypes.length > 0) {
        maxScore += 30;
        if (criteria.propTypes.includes(prop.propType)) {
          score += 30;
          reasons.push(`Matches requested ${prop.propType} market`);
        }
      }

      // player type match
      if (criteria.playerType !== "any") {
        maxScore += 20;
        const match = (criteria.playerType === "pitcher" && isPitcherProp) ||
                      (criteria.playerType === "hitter" && !isPitcherProp);
        if (match) { score += 20; reasons.push(`${criteria.playerType} prop type matches`); }
      }

      // confidence threshold
      maxScore += 25;
      if (prop.confidence >= criteria.minConfidence) {
        score += 25;
        reasons.push(`${prop.confidence}% confidence meets ${criteria.minConfidence}%+ threshold`);
      } else {
        score += Math.max(0, Math.floor(25 * (prop.confidence / criteria.minConfidence)));
      }

      // L10 hit rate
      if (criteria.minL10 > 0) {
        maxScore += 20;
        if (prop.hitRates.last10 >= criteria.minL10) {
          score += 20;
          reasons.push(`L10 hit rate ${prop.hitRates.last10}% exceeds ${criteria.minL10}% threshold`);
        }
      }

      // side
      if (criteria.side !== "any") {
        maxScore += 15;
        if (prop.researchSide === criteria.side) {
          score += 15;
          reasons.push(`${criteria.side} market matches request`);
        }
      }

      // plus money
      if (criteria.plusMoneyOnly) {
        maxScore += 20;
        if (propOdds > 0) { score += 20; reasons.push(`Plus-money odds (${prop.overOdds})`); }
      }

      // team filter
      if (criteria.teams.length > 0) {
        maxScore += 15;
        if (criteria.teams.includes(prop.team) || criteria.teams.some((t) => prop.opponent.includes(t))) {
          score += 15; reasons.push(`Involves ${prop.team}`);
        }
      }

      // projected PA bonus
      if (prop.projectedPlateAppearances && prop.projectedPlateAppearances >= 4) {
        reasons.push(`High projected PA (${prop.projectedPlateAppearances})`);
      }

      // recent form bonus
      if (prop.hitRates.last5 >= 70) reasons.push(`Strong L5 hit rate (${prop.hitRates.last5}%)`);

      const basePct = maxScore > 0 ? (score / maxScore) : 1;
      // Blend with confidence for final score
      const matchScore = Math.min(99, Math.round(basePct * 80 + (prop.confidence / 100) * 20));

      // ── risk ───────────────────────────────────────────────────────────────
      const highVariance = ["HomeRuns", "Home Runs"].includes(prop.propType);
      const riskLevel: "LOW" | "MEDIUM" | "HIGH" =
        highVariance || propOdds > 150 || prop.confidence < 65 ? "HIGH" :
        prop.confidence >= 78 && !highVariance ? "LOW" : "MEDIUM";

      if (highVariance) riskNotes.push("Home run props carry inherent variance");
      if (propOdds > 100) riskNotes.push(`Plus-money reflects lower market implied probability`);
      if (prop.hitRates.last5 < 60) riskNotes.push("Recent L5 trend is below average");
      if (riskNotes.length === 0) riskNotes.push("Standard market risk applies");

      const aiReason = prop.rationale ||
        `${prop.player} shows ${prop.confidence >= 75 ? "strong" : "solid"} ${prop.propType.toLowerCase()} potential based on recent form and matchup context.`;

      if (criteria.riskLevel !== "any" && criteria.riskLevel !== riskLevel) {
        if (matchScore < 50) return null;
      }

      return {
        prop, matchScore, riskLevel,
        matchReasons: reasons.slice(0, 4),
        riskNotes: riskNotes.slice(0, 2),
        aiReason,
      };
    })
    .filter((r): r is AiResult => r !== null);

  return scored
    .sort((a, b) => {
      const scoreDiff = (b.matchScore - a.matchScore) * 0.6;
      const confDiff = (b.prop.confidence - a.prop.confidence) * 0.4;
      return scoreDiff + confDiff;
    })
    .slice(0, criteria.maxResults);
}

/** Generate structured criteria display rows for the AI Interpretation panel. */
export function getCriteriaRows(criteria: AiSearchCriteria) {
  const rows: Array<{ label: string; value: string }> = [];
  rows.push({ label: "Sport", value: criteria.sport });
  if (criteria.playerType !== "any")
    rows.push({ label: "Player Type", value: criteria.playerType.charAt(0).toUpperCase() + criteria.playerType.slice(1) + "s" });
  if (criteria.propTypes.length > 0)
    rows.push({ label: "Markets", value: criteria.propTypes.join(", ") });
  if (criteria.side !== "any")
    rows.push({ label: "Side", value: criteria.side });
  rows.push({ label: "Min Confidence", value: `${criteria.minConfidence}%+` });
  if (criteria.minL10 > 0)
    rows.push({ label: "Min L10 Hit Rate", value: `${criteria.minL10}%+` });
  if (criteria.riskLevel !== "any")
    rows.push({ label: "Risk", value: criteria.riskLevel });
  if (criteria.plusMoneyOnly)
    rows.push({ label: "Odds", value: "Plus-money only" });
  if (criteria.teams.length > 0)
    rows.push({ label: "Teams", value: criteria.teams.join(", ") });
  rows.push({ label: "Max Results", value: String(criteria.maxResults) });
  return rows;
}

lib/ai/probabilityModel.ts:
/**
 * DeepSide market probability model.
 *
 * Estimates P(stat clears the sportsbook line) from the modelled distribution of a player's
 * expected outcome — NOT from historical hit rate, and never from researchScore. Historical
 * performance enters only later, as bounded calibration evidence (see calibrateProbability).
 *
 * Every market is mapped to a distribution family appropriate to the underlying stat. When the
 * inputs required by that family are missing, the model returns null and the caller fails closed.
 */

export type MarketFamily = 'RARE_COUNT' | 'COUNT' | 'VOLUME';
export type DistributionUsed = 'poisson' | 'negative_binomial' | 'normal';

export interface ModelProbabilityResult {
  probability: number;
  distribution: DistributionUsed;
  family: MarketFamily;
  /** Standardised separation between projection and line; sign follows the bet direction. */
  zSeparation: number | null;
  basis: string;
}

/**
 * Market -> distribution family.
 * RARE_COUNT: low-mean integer events where variance ≈ mean; Poisson is the natural model.
 * COUNT:      integer counts that are usually overdispersed; negative binomial when we have a
 *             variance estimate that exceeds the mean, Poisson otherwise.
 * VOLUME:     large counts/continuous-ish totals where a normal approximation is reasonable.
 */
const MARKET_FAMILY: Record<string, MarketFamily> = {
  batter_home_runs: 'RARE_COUNT',
  batter_doubles: 'RARE_COUNT',
  batter_triples: 'RARE_COUNT',
  batter_stolen_bases: 'RARE_COUNT',
  batter_hits: 'COUNT',
  batter_runs_scored: 'COUNT',
  batter_rbis: 'COUNT',
  batter_walks: 'COUNT',
  batter_total_bases: 'COUNT',
  batter_hits_runs_rbis: 'COUNT',
  batter_strikeouts: 'COUNT',
  pitcher_strikeouts: 'COUNT',
  pitcher_hits_allowed: 'COUNT',
  pitcher_earned_runs: 'COUNT',
  pitcher_walks: 'COUNT',
  pitcher_outs: 'VOLUME',
  player_pass_yds: 'VOLUME',
  player_rush_yds: 'VOLUME',
  player_reception_yds: 'VOLUME',
  player_rush_rec_yds: 'VOLUME',
  player_receptions: 'COUNT',
  player_pass_attempts: 'COUNT',
  player_pass_completions: 'COUNT',
  player_rush_attempts: 'COUNT',
  player_tackles_assists: 'COUNT',
  player_solo_tackles: 'COUNT',
  player_pass_tds: 'RARE_COUNT',
  player_rush_tds: 'RARE_COUNT',
  player_reception_tds: 'RARE_COUNT',
  player_pass_interceptions: 'RARE_COUNT',
  player_defensive_interceptions: 'RARE_COUNT',
  player_sacks: 'RARE_COUNT',
  player_anytime_td: 'RARE_COUNT',
  // NBA — high-volume box-score totals behave continuously; low-count events stay count-based.
  points: 'VOLUME',
  rebounds: 'COUNT',
  assists: 'COUNT',
  pra: 'VOLUME',
  pr: 'VOLUME',
  pa: 'VOLUME',
  ra: 'VOLUME',
  minutes: 'VOLUME',
  '3pm': 'COUNT',
  steals: 'RARE_COUNT',
  blocks: 'RARE_COUNT',
  turnovers: 'COUNT',
};

/** Minimum games required before a family's variance/mean estimates are trusted. */
export const MIN_SAMPLE_BY_FAMILY: Record<MarketFamily, number> = {
  RARE_COUNT: 10,
  COUNT: 10,
  VOLUME: 10,
};

export function getMarketFamily(marketKey: string): MarketFamily | null {
  return MARKET_FAMILY[marketKey] ?? null;
}

// ── distribution helpers ──────────────────────────────────────────────────────

/** Lanczos log-gamma, used for negative-binomial terms with non-integer r. */
function logGamma(x: number): number {
  const g = [
    676.5203681218851, -1259.1392167224028, 771.32342877765313,
    -176.61502916214059, 12.507343278686905, -0.13857109526572012,
    9.9843695780195716e-6, 1.5056327351493116e-7,
  ];
  if (x < 0.5) return Math.log(Math.PI / Math.sin(Math.PI * x)) - logGamma(1 - x);
  const z = x - 1;
  let a = 0.99999999999980993;
  const t = z + 7.5;
  for (let i = 0; i < g.length; i += 1) a += g[i] / (z + i + 1);
  return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(a);
}

/** P(X <= k) for Poisson(lambda). */
function poissonCdf(k: number, lambda: number): number {
  if (k < 0) return 0;
  if (lambda <= 0) return 1;
  let term = Math.exp(-lambda);
  let sum = term;
  for (let i = 1; i <= k; i += 1) {
    term *= lambda / i;
    sum += term;
  }
  return Math.min(1, sum);
}

/** P(X <= k) for a negative binomial with mean `mean` and variance `variance` (variance > mean). */
function negBinomCdf(k: number, mean: number, variance: number): number {
  if (k < 0) return 0;
  const r = (mean * mean) / (variance - mean);
  const p = r / (r + mean);
  let sum = 0;
  for (let i = 0; i <= k; i += 1) {
    const logPmf = logGamma(i + r) - logGamma(r) - logGamma(i + 1) + r * Math.log(p) + i * Math.log1p(-p);
    sum += Math.exp(logPmf);
  }
  return Math.min(1, sum);
}

/** Standard normal CDF via Abramowitz-Stegun erf approximation. */
function normalCdf(z: number): number {
  const t = 1 / (1 + 0.2316419 * Math.abs(z));
  const d = 0.3989422804014327 * Math.exp(-z * z / 2);
  const prob = d * t * (0.319381530 + t * (-0.356563782 + t * (1.781477937 + t * (-1.821255978 + t * 1.330274429))));
  return z > 0 ? 1 - prob : prob;
}

/**
 * Models P(stat clears the line) for this candidate's direction.
 *
 * Inputs: projection (distribution mean), projectionUncertainty (spread), line, direction, market.
 * Returns null — never a guess — when the market is unmapped, the projection is missing, the sample
 * is too small for the family, or the family needs a spread estimate that is unavailable.
 */
export function modelProbability(params: {
  marketKey: string;
  line: number | null;
  direction: 'over' | 'under';
  projection: number | null;
  projectionUncertainty: number | null;
  sampleSize: number | null;
}): ModelProbabilityResult | null {
  const { marketKey, line, direction, projection, projectionUncertainty, sampleSize } = params;
  const family = getMarketFamily(marketKey);
  if (family == null || line == null || projection == null || projection < 0) return null;
  if (sampleSize == null || sampleSize < MIN_SAMPLE_BY_FAMILY[family]) return null;

  let probabilityOver: number;
  let distribution: DistributionUsed;

  if (family === 'VOLUME') {
    // Normal approximation needs a real spread estimate; without one we fail closed.
    if (projectionUncertainty == null || projectionUncertainty <= 0) return null;
    // Lines are x.5, so no continuity correction is needed for the tie case.
    probabilityOver = 1 - normalCdf((line - projection) / projectionUncertainty);
    distribution = 'normal';
  } else {
    // Integer counts: P(X > line) = 1 - P(X <= floor(line)).
    const k = Math.floor(line);
    const variance = projectionUncertainty != null && projectionUncertainty > 0 ? projectionUncertainty ** 2 : null;
    if (family === 'COUNT' && variance != null && variance > projection && projection > 0) {
      probabilityOver = 1 - negBinomCdf(k, projection, variance);
      distribution = 'negative_binomial';
    } else {
      probabilityOver = 1 - poissonCdf(k, projection);
      distribution = 'poisson';
    }
  }

  const probability = direction === 'over' ? probabilityOver : 1 - probabilityOver;
  // Epistemic bound: the projection itself is estimated from `sampleSize` games, so no finite sample
  // can justify more confidence than a Laplace-style 1 - 1/(n+2). Without this, a projection of ~0 in
  // a rare-event market returns ~99.9%, which the calibration backtest showed to be overconfident.
  const maxConfidence = 1 - 1 / (sampleSize + 2);
  const bounded = Math.max(1 - maxConfidence, Math.min(maxConfidence, probability));
  const zSeparation = projectionUncertainty != null && projectionUncertainty > 0
    ? (direction === 'over' ? projection - line : line - projection) / projectionUncertainty
    : null;

  return {
    probability: bounded,
    distribution,
    family,
    zSeparation: zSeparation != null ? Number(zSeparation.toFixed(2)) : null,
    basis: `${distribution} on ${family} market (mean=${projection}, spread=${projectionUncertainty ?? 'n/a'}, line=${line}, ${direction}), confidence bounded to ${(maxConfidence * 100).toFixed(1)}% by a ${sampleSize}-game sample`,
  };
}

export interface CalibratedProbability {
  modelProbability: number;
  historicalHitRate: number | null;
  calibratedProbability: number;
  /** Weight given to historical evidence; capped so history can never become the probability. */
  historicalWeight: number;
  /** |model - historical|; large values flag an unstable or biased projection. */
  divergence: number | null;
  basis: string;
}

/** Historical evidence may nudge the modelled probability, but is capped so it can never replace it. */
export const MAX_HISTORICAL_WEIGHT = 0.35;

/**
 * Blends the modelled probability with the observed hit rate as SUPPORTING evidence only.
 *   w = min(MAX_HISTORICAL_WEIGHT, n / (n + 20))
 *   calibrated = (1 - w) * model + w * historical
 * Clamped to [0.02, 0.98] so nothing is ever asserted as a near-certainty.
 */
export function calibrateProbability(params: {
  modelProbability: number;
  historicalHitRate: number | null;
  sampleSize: number | null;
}): CalibratedProbability {
  const { modelProbability: model, historicalHitRate, sampleSize } = params;
  const n = sampleSize ?? 0;
  const weight = historicalHitRate != null && n > 0
    ? Math.min(MAX_HISTORICAL_WEIGHT, n / (n + 20))
    : 0;
  const blended = historicalHitRate != null ? (1 - weight) * model + weight * historicalHitRate : model;
  return {
    modelProbability: model,
    historicalHitRate,
    calibratedProbability: Math.max(0.02, Math.min(0.98, blended)),
    historicalWeight: Number(weight.toFixed(3)),
    divergence: historicalHitRate != null ? Number(Math.abs(model - historicalHitRate).toFixed(3)) : null,
    basis: `Model probability calibrated with ${(weight * 100).toFixed(0)}% weight on ${n}-game historical hit rate`,
  };
}

lib/ai/refreshBudget.ts:
export const CONSERVATIVE_VALIDATION_COST_PER_GAME = 31;

export function canAuthorizeFullSlate(maximumEstimatedCost: number | null, availableCredits: number | null): boolean {
  return maximumEstimatedCost != null && availableCredits != null && maximumEstimatedCost <= availableCredits;
}

/**
 * How many games an authorized budget can actually research.
 *
 * `costPerPaidGame` must be the sport's own conservative per-game estimate (MLB ~31, NFL ~61) so the
 * count never promises more games than the credit cap can pay for. `freeGames` are games whose props
 * are already cached: they spend nothing, so they are researchable on any budget and are what allows
 * a small cap to still return research instead of blocking.
 */
export function safelyResearchableGames(
  budget: number,
  scheduledGames: number,
  costPerPaidGame: number = CONSERVATIVE_VALIDATION_COST_PER_GAME,
  freeGames = 0,
): number {
  if (scheduledGames <= 0) return 0;
  const free = Math.min(scheduledGames, Math.max(0, freeGames));
  const perGame = Number.isFinite(costPerPaidGame) && costPerPaidGame > 0 ? costPerPaidGame : CONSERVATIVE_VALIDATION_COST_PER_GAME;
  const affordablePaidGames = Number.isFinite(budget) && budget > 0 ? Math.floor(budget / perGame) : 0;
  return Math.min(scheduledGames, free + affordablePaidGames);
}

