/**
 * Centralized date/slate model for Research Lab + AI Finder.
 * Every date-aware request in the app should go through this module instead of
 * calling `new Date()` directly, so "today" is computed exactly once, consistently.
 */

export type SlateDate = string; // YYYY-MM-DD
export const SPORTS_TIME_ZONE = 'America/New_York';

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

export function isValidSlateDate(value: string | null | undefined): value is SlateDate {
  if (!value || !DATE_PATTERN.test(value)) return false;
  const [y, m, d] = value.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  return date.getUTCFullYear() === y && date.getUTCMonth() === m - 1 && date.getUTCDate() === d;
}

function toSlateDate(date: Date): SlateDate {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: SPORTS_TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);
  const values = Object.fromEntries(parts.map((part) => [part.type, part.value]));
  return `${values.year}-${values.month}-${values.day}`;
}

/** Sports "today" in the application's Eastern calendar. */
export function todaySlateDate(): SlateDate {
  return toSlateDate(new Date());
}

export function tomorrowSlateDate(): SlateDate {
  return addDaysToSlateDate(todaySlateDate(), 1);
}

export function addDaysToSlateDate(date: SlateDate, days: number): SlateDate {
  const [y, m, d] = date.split('-').map(Number);
  const parsed = new Date(Date.UTC(y, m - 1, d));
  parsed.setUTCDate(parsed.getUTCDate() + days);
  return parsed.toISOString().slice(0, 10);
}

/** Resolves an untrusted (e.g. URL) date param to a valid slate date, defaulting to today. */
export function resolveSlateDate(value: string | null | undefined): SlateDate {
  return isValidSlateDate(value) ? value : todaySlateDate();
}

export type NaturalDateIntent = 'today' | 'tonight' | 'tomorrow';

export function dateIntentFromText(value: string): NaturalDateIntent | null {
  const text = value.toLowerCase();
  if (/\btomorrow\b/.test(text)) return 'tomorrow';
  if (/\btonight\b/.test(text)) return 'tonight';
  if (/\btoday\b/.test(text)) return 'today';
  return null;
}

export function slateDateForIntent(intent: NaturalDateIntent): SlateDate {
  return intent === 'tomorrow' ? tomorrowSlateDate() : todaySlateDate();
}

export type DatePreset = 'today' | 'tomorrow';

export function presetForSlateDate(date: SlateDate): DatePreset | null {
  if (date === todaySlateDate()) return 'today';
  if (date === tomorrowSlateDate()) return 'tomorrow';
  return null;
}

export function slateDateForPreset(preset: DatePreset): SlateDate {
  return preset === 'tomorrow' ? tomorrowSlateDate() : todaySlateDate();
}

/** ESPN's scoreboard `dates` param wants YYYYMMDD (no dashes). */
export function toEspnDateParam(date: SlateDate): string {
  return date.replace(/-/g, '');
}

export function formatSlateDateLabel(date: SlateDate): string {
  const preset = presetForSlateDate(date);
  if (preset === 'today') return 'Today';
  if (preset === 'tomorrow') return 'Tomorrow';
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d)).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
}

lib/finder/alternateLineOptimizer.ts:
import { americanToImpliedProbability, expectedValuePercent, removeTwoWayVig } from '../odds/math';
import type { NormalizedProp } from '../odds/types';

export type AlternateLineBand = 'GO' | 'PLAYABLE' | 'MARGINAL' | 'PASS';

export interface AlternateLineOption {
  line: number;
  side: 'over' | 'under';
  bestBook: string | null;
  bestOdds: number | null;
  /** Vig-removed fair probability (%), from books that post both sides of this line. Null if unavailable. */
  trueProbability: number | null;
  /** Implied probability (%) of the best offered price alone — what you'd need to hit to break even. */
  breakEvenProbability: number | null;
  edgePercent: number | null;
  band: AlternateLineBand;
}

export interface AlternateLineOptimizerResult {
  available: boolean;
  side: 'over' | 'under';
  /** Every threshold actually posted for this player+market, from the real props already fetched for this event. */
  options: AlternateLineOption[];
  recommended: AlternateLineOption | null;
}

function bandFor(edgePercent: number | null, trueProbability: number | null): AlternateLineBand {
  if (edgePercent == null) return 'PASS';
  if (edgePercent >= 5 && trueProbability != null && trueProbability >= 0.55) return 'GO';
  if (edgePercent >= 2) return 'PLAYABLE';
  if (edgePercent >= -2) return 'MARGINAL';
  return 'PASS';
}

/**
 * Compares every real posted threshold (standard + alternate) for one player+market from the props
 * already fetched for this event, and recommends the best risk-adjusted one. Makes no new requests —
 * operates only on data DeepSide has already paid for and cached.
 */
export function computeAlternateLineOptimizer(
  eventProps: NormalizedProp[],
  player: string,
  canonicalMarketKey: string,
  side: 'over' | 'under',
): AlternateLineOptimizerResult {
  const relevant = eventProps.filter((prop) => prop.player === player && prop.marketKey === canonicalMarketKey);
  if (relevant.length === 0) return { available: false, side, options: [], recommended: null };

  const byLine = new Map<number, NormalizedProp[]>();
  for (const prop of relevant) byLine.set(prop.line, [...(byLine.get(prop.line) ?? []), prop]);

  const options: AlternateLineOption[] = [];
  for (const [line, props] of byLine) {
    const paired = props.filter((prop) => prop.overOdds != null && prop.underOdds != null);
    const probs = paired
      .map((prop) => removeTwoWayVig(prop.overOdds!, prop.underOdds!)?.[side])
      .filter((value): value is number => value != null);
    const trueProbability = probs.length ? probs.reduce((sum, value) => sum + value, 0) / probs.length : null;

    const sideOdds = props.map((prop) => (side === 'over' ? prop.overOdds : prop.underOdds)).filter((value): value is number => value != null);
    if (!sideOdds.length) continue;
    const bestOddsValue = sideOdds.reduce((best, odds) => (odds > best ? odds : best), sideOdds[0]);
    const bestBookProp = props.find((prop) => (side === 'over' ? prop.overOdds : prop.underOdds) === bestOddsValue);
    const breakEvenProbability = americanToImpliedProbability(bestOddsValue);
    const edgePercent = trueProbability != null ? expectedValuePercent(trueProbability, bestOddsValue) : null;

    options.push({
      line,
      side,
      bestBook: bestBookProp?.sportsbookName ?? null,
      bestOdds: bestOddsValue,
      trueProbability: trueProbability != null ? Number((trueProbability * 100).toFixed(1)) : null,
      breakEvenProbability: breakEvenProbability != null ? Number((breakEvenProbability * 100).toFixed(1)) : null,
      edgePercent: edgePercent != null ? Number(edgePercent.toFixed(1)) : null,
      band: bandFor(edgePercent, trueProbability),
    });
  }

  options.sort((a, b) => (side === 'over' ? a.line - b.line : b.line - a.line));
  const playable = options.filter((option) => option.band === 'GO' || option.band === 'PLAYABLE');
  const recommended = playable.length
    ? playable.reduce((best, option) => ((option.edgePercent ?? -Infinity) > (best.edgePercent ?? -Infinity) ? option : best), playable[0])
    : null;

  return { available: options.length > 0, side, options, recommended };
}

lib/finder/confidenceGrade.ts:
import type { EliteResearchAnalysis } from '../ai/eliteResearchFilter';
import type { OutlierDependency } from './outlierAnalysis';
import type { VolumeEfficiency } from './volumeEfficiency';

export type ConfidenceGrade = 'A+' | 'A' | 'A-' | 'B+' | 'B' | 'C' | 'D' | 'F';

/**
 * A letter grade layered ON TOP of the Elite Filter — it never changes `eliteQualified`, only adds
 * finer differentiation. A candidate that is not Elite-qualified can never grade above C, and A+/A
 * additionally require passing the outlier-dependency and volume-efficiency checks, so a technically
 * qualified pick that is secretly one outlier game away from missing still gets capped at B+.
 */
export function computeConfidenceGrade(params: {
  analysis: EliteResearchAnalysis;
  outlier: OutlierDependency;
  volumeEfficiency: VolumeEfficiency;
}): ConfidenceGrade {
  const { analysis, outlier, volumeEfficiency } = params;

  if (analysis.rejectedReasons.length > 0 || analysis.dataQuality < 50) return 'F';

  if (!analysis.eliteQualified) {
    if (analysis.researchScore >= 75 && analysis.trapRisk <= 35) return 'C';
    if (analysis.researchScore >= 60) return 'D';
    return 'F';
  }

  const outlierRisk = outlier.available && outlier.explosiveDependencePercent != null && outlier.explosiveDependencePercent >= 35;
  const volumeRisk = volumeEfficiency.available && volumeEfficiency.meetsRequiredRate === false;
  if (outlierRisk || volumeRisk) return 'B+';

  const fullAgreement = (analysis.agreementRatio ?? 0) >= 1;
  if (analysis.researchScore >= 95 && fullAgreement && analysis.trapRisk <= 10) return 'A+';
  if (analysis.researchScore >= 90 && fullAgreement) return 'A';
  return 'A-';
}

lib/finder/crossBookThreshold.ts:
import type { NormalizedProp } from '../odds/types';

export interface CrossBookThresholdResult {
  available: boolean;
  standardLines: Array<{ line: number; books: string[] }>;
  discrepancy: boolean;
  spread: number | null;
}

/** Flags when sportsbooks disagree on the standard-line threshold for the same player+market, from data already fetched for this event. */
export function computeCrossBookThreshold(eventProps: NormalizedProp[], player: string, canonicalMarketKey: string): CrossBookThresholdResult {
  const standard = eventProps.filter((prop) => prop.player === player && prop.marketKey === canonicalMarketKey && !prop.isAlternate);
  if (standard.length === 0) return { available: false, standardLines: [], discrepancy: false, spread: null };

  const byLine = new Map<number, Set<string>>();
  for (const prop of standard) {
    const books = byLine.get(prop.line) ?? new Set<string>();
    books.add(prop.sportsbookName);
    byLine.set(prop.line, books);
  }

  const standardLines = [...byLine.entries()].map(([line, books]) => ({ line, books: [...books] })).sort((a, b) => a.line - b.line);
  const lines = standardLines.map((entry) => entry.line);
  const spread = lines.length > 1 ? Number((Math.max(...lines) - Math.min(...lines)).toFixed(2)) : 0;
  return { available: true, standardLines, discrepancy: lines.length > 1, spread };
}

