  id: number;
  name: string;
  displayName: string;
  abbreviation: string;
  logoUrl: string | null;
  color: string | null;
}

export type NFLPosition = 'QB' | 'RB' | 'WR' | 'TE' | 'K' | 'DEF' | string;

export interface NFLPlayer {
  id: number;
  name: string;
  position: NFLPosition;
  positionName: string | null;
