export type AnalyzableMarketKey =
  | 'batter_hits'
  | 'batter_total_bases'
  | 'batter_home_runs'
  | 'batter_rbis'
  | 'batter_runs_scored'
  | 'batter_hits_runs_rbis'
  | 'batter_strikeouts'
  | 'pitcher_strikeouts'
  | 'pitcher_hits_allowed'
  | 'pitcher_earned_runs'
  | 'pitcher_outs';

export type OddsMarketKey = string;
export type SupportedOddsMarketKey = string;
export type AlternateOddsMarketKey = string;

export const HITTER_MARKETS: AnalyzableMarketKey[] = [
  'batter_hits', 'batter_total_bases', 'batter_home_runs', 'batter_rbis', 'batter_runs_scored', 'batter_hits_runs_rbis', 'batter_strikeouts',
];

export const PITCHER_MARKETS: AnalyzableMarketKey[] = [
  'pitcher_strikeouts', 'pitcher_hits_allowed', 'pitcher_earned_runs', 'pitcher_outs',
];

export const ALTERNATE_HITTER_MARKETS: string[] = [
  'batter_hits_alternate', 'batter_total_bases_alternate', 'batter_home_runs_alternate', 'batter_rbis_alternate', 'batter_runs_scored_alternate', 'batter_hits_runs_rbis_alternate', 'batter_strikeouts_alternate',
];

export const ALTERNATE_PITCHER_MARKETS: string[] = [
  'pitcher_strikeouts_alternate', 'pitcher_hits_allowed_alternate', 'pitcher_earned_runs_alternate', 'pitcher_outs_alternate',
];

export const MARKET_LABELS: Record<AnalyzableMarketKey, string> = {
  batter_hits: 'Hits',
  batter_total_bases: 'Total Bases',
  batter_home_runs: 'Home Runs',
  batter_rbis: 'RBIs',
  batter_runs_scored: 'Runs',
  batter_hits_runs_rbis: 'Hits + Runs + RBIs',
  batter_strikeouts: 'Strikeouts',
  pitcher_strikeouts: 'Pitcher Strikeouts',
  pitcher_hits_allowed: 'Hits Allowed',
  pitcher_earned_runs: 'Earned Runs',
  pitcher_outs: 'Outs Recorded',
};

const DISPLAY_LABELS: Record<string, string> = {
  ...MARKET_LABELS,
  batter_singles: 'Singles', batter_doubles: 'Doubles', batter_triples: 'Triples', batter_walks: 'Walks', batter_stolen_bases: 'Stolen Bases', batter_fantasy_score: 'Batter Fantasy Score',
  pitcher_walks: 'Walks Allowed', pitcher_home_runs_allowed: 'Home Runs Allowed', pitcher_fantasy_score: 'Pitcher Fantasy Score',
};

export interface MarketMetadata {
  sourceMarketKey: string;
  canonicalMarketKey: string;
  label: string;
  isAlternate: boolean;
  isPitcher: boolean;
  historicalAnalysisAvailable: boolean;
}

export function getMarketMetadata(sourceMarketKey: string): MarketMetadata | null {
  const isAlternate = sourceMarketKey.endsWith('_alternate');
  const canonicalMarketKey = isAlternate ? sourceMarketKey.slice(0, -'_alternate'.length) : sourceMarketKey;
  if (!canonicalMarketKey.startsWith('batter_') && !canonicalMarketKey.startsWith('pitcher_')) return null;
  const label = DISPLAY_LABELS[canonicalMarketKey] ?? canonicalMarketKey.replace(/^(batter|pitcher)_/, '').split('_').map((word) => word[0].toUpperCase() + word.slice(1)).join(' ');
  return {
    sourceMarketKey,
    canonicalMarketKey,
    label,
    isAlternate,
    isPitcher: canonicalMarketKey.startsWith('pitcher_'),
    historicalAnalysisAvailable: canonicalMarketKey in MARKET_LABELS || ['batter_doubles', 'batter_triples', 'batter_walks'].includes(canonicalMarketKey),
  };
}

export interface OddsEvent {
  id: string;
  commenceTime: string;
  homeTeam: string;
  awayTeam: string;
}

export interface NormalizedProp {
  sport?: 'mlb' | 'nfl' | 'nba';
  player: string;
  playerId?: number | null;
  marketKey: OddsMarketKey;
  sourceMarketKey: SupportedOddsMarketKey;
  isAlternate: boolean;
  historicalAnalysisAvailable: boolean;
  marketLabel: string;
  line: number;
  overOdds: number | null;
  underOdds: number | null;
  sportsbookKey: string;
  sportsbookName: string;
  eventId: string;
  lastUpdate: string;
}

lib/projection/types.ts:
/**
 * Cross-sport projection contract.
 *
 * Every sport computes projections its own way (NBA uses rate x minutes, NFL uses a short-season
 * historical baseline), but all of them report the result in this shape so downstream consumers —
 * the Elite Filter, probability model and Finder — never need sport-specific branching.
 *
 * The contract exists to make projection TRUST explicit. A number alone is not enough: callers must
 * be able to see how reliable it is and why, and an UNRELIABLE projection must never back an
 * official Elite candidate.
 */

/**
 * HIGH       – large sample, stable role, low volatility.
 * MEDIUM     – usable, with a named caveat (moderate sample or volatility).
 * LOW        – real data but a material trust problem; not Elite-eligible.
 * UNRELIABLE – critical context missing or contradictory; must fail closed.
 */
export type ProjectionReliability = 'HIGH' | 'MEDIUM' | 'LOW' | 'UNRELIABLE';

/** Machine-readable reasons behind a reliability grade. Never free text, so callers can branch. */
export type ProjectionReliabilityReason =
  | 'INSUFFICIENT_SAMPLE'
  | 'SMALL_SAMPLE'
  | 'INSUFFICIENT_MINUTES_SAMPLE'
  | 'HIGH_MINUTES_VOLATILITY'
  | 'HIGH_RATE_VOLATILITY'
  | 'ROLE_DECREASE'
  | 'ROLE_INCREASE'
  | 'RECENT_MINUTES_CHANGE'
  | 'INJURY_STATUS_UNKNOWN'
  | 'INJURY_LISTED'
  | 'MISSING_COMPONENT'
  | 'MISSING_STAT'
  | 'DERIVED_COVARIANCE_UNAVAILABLE'
  | 'ROLE_CONTEXT_UNAVAILABLE'
  | 'SHORT_SEASON_SAMPLE';

export type ProjectionStatus = 'OK' | 'UNAVAILABLE';

/** What a sport's projection engine returns for one player+market. */
export interface SportProjection {
  status: ProjectionStatus;
  /** Expected value of the stat. Null whenever status is UNAVAILABLE — never a fabricated 0. */
  projection: number | null;
  /** Standard-deviation-style spread of the projection. Null when it cannot be estimated. */
  uncertainty: number | null;
  /** Games that actually contributed to the estimate (not games requested). */
  sampleSize: number;
  reliability: ProjectionReliability;
  reliabilityReasons: ProjectionReliabilityReason[];
  /** Short identifier of the formula used, e.g. 'nba_rate_x_minutes'. */
  method: string;
  /** Sport-specific intermediate values, surfaced for auditability. Never used for qualification. */
  inputs: Record<string, number | string | null>;
}

export function unavailableProjection(method: string, reasons: ProjectionReliabilityReason[], inputs: SportProjection['inputs'] = {}): SportProjection {
  return { status: 'UNAVAILABLE', projection: null, uncertainty: null, sampleSize: 0, reliability: 'UNRELIABLE', reliabilityReasons: reasons, method, inputs };
}

/** Only HIGH/MEDIUM projections may back an official Elite candidate. */
export function isEliteEligibleProjection(projection: SportProjection): boolean {
  return projection.status === 'OK' && (projection.reliability === 'HIGH' || projection.reliability === 'MEDIUM');
}

export function mean(values: number[]): number | null {
  return values.length ? values.reduce((s, v) => s + v, 0) / values.length : null;
}

export function standardDeviation(values: number[]): number | null {
  if (values.length < 2) return null;
  const m = values.reduce((s, v) => s + v, 0) / values.length;
  return Math.sqrt(values.reduce((s, v) => s + (v - m) ** 2, 0) / (values.length - 1));
}

export function median(values: number[]): number | null {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

